ENTRY(cpu_switch)
        /* Store the new curthread */
        sd      a1, PC_CURTHREAD(tp)
        /* And the new pcb */
        ld      x13, TD_PCB(a1)
        sd      x13, PC_CURPCB(tp)

        /* Save the old context. */
        ld      x13, TD_PCB(a0)

        /* Store ra, sp and the callee-saved registers */
        sd      ra, (PCB_RA)(x13)
        sd      sp, (PCB_SP)(x13)
        /* s[0-11] */
        ...
        /* NO sctrctl save/restore anywhere in this function */

struct pcb {
        uint64_t        pcb_ra;
        uint64_t        pcb_sp;
        uint64_t        pcb_gp;
        uint64_t        pcb_tp;
        uint64_t        pcb_s[12];
        uint64_t        pcb_x[32][2];
        uint64_t        pcb_fcsr;
        uint64_t        pcb_fpflags;
#define PCB_FP_STARTED  0x1
#define PCB_FP_USERMASK 0x1
        vm_offset_t     pcb_onfault;
        /* NO pcb_sctrctl field */
};

exec_setregs(struct thread *td, struct image_params *imgp, uintptr_t stack)
{
        struct trapframe *tf;
        struct pcb *pcb;

        tf = td->td_frame;
        pcb = td->td_pcb;

        memset(tf, 0, sizeof(struct trapframe));
        ...
        pcb->pcb_fpflags &= ~PCB_FP_STARTED;
        /* NO sctrctl reset to zero */
}

get_mcontext(struct thread *td, mcontext_t *mcp, int clear_ret)
{
        struct trapframe *tf = td->td_frame;

        memcpy(mcp->mc_gpregs.gp_t, tf->tf_t, sizeof(mcp->mc_gpregs.gp_t));
        ...
        mcp->mc_gpregs.gp_sstatus = tf->tf_sstatus;
        get_fpcontext(td, mcp);
        /* NO sctrctl read */
        return (0);
}

set_mcontext(struct thread *td, mcontext_t *mcp)
{
        ...
        if (((mcp->mc_gpregs.gp_sstatus ^ tf->tf_sstatus) &
            ~(SSTATUS_SD | SSTATUS_XS_MASK | SSTATUS_FS_MASK | SSTATUS_UPIE |
            SSTATUS_UIE)) != 0)
                return (EINVAL);
        /* Validates sstatus but NOT sctrctl */
        ...
        set_fpcontext(td, mcp);
        /* NO sctrctl restore */
        return (0);
}

struct trapframe {
        uint64_t tf_ra;
        uint64_t tf_sp;
        uint64_t tf_gp;
        uint64_t tf_tp;
        uint64_t tf_t[7];
        uint64_t tf_s[12];
        uint64_t tf_a[8];
        uint64_t tf_sepc;
        uint64_t tf_sstatus;
        uint64_t tf_stval;
        uint64_t tf_scause;
        /* NO tf_sctrctl field */
};

